INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 11, 'theory', 'Quiz: Python and Rust strings');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 11, 0, 'What does the find method of a Rust string return if the substring is missing?', '["-1, as in Python", "0", "None — a value of type Option<usize>", "a panic"]', 2, 'Option keeps you from confusing “no substring” with a position; in Python it is easy to forget the -1 check.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 11, 1, 'What replaces the Python call " ".join(words)?', '["words.join(\" \")", "join(words, \" \")", "words.concat(\" \")", "String::join(\" \", words)"]', 0, 'join is called on a slice or a vector of strings; the separator is the argument.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 11, 2, 'What does from_utf8 return for a set of bytes?', '["a String right away", "Option<String>", "Vec<char>", "Result<String, _> — the bytes may not be UTF-8"]', 3, 'For data from unknown sources there is from_utf8_lossy, which replaces invalid bytes with a special character.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 11, 3, 'Why can "straße".to_uppercase() be longer than the original string?', '["it is a language bug", "because a null byte is appended to the string", "when changing case, «ß» turns into «SS»", "to_uppercase always doubles the string"]', 2, 'Case conversion by Unicode rules can turn one character into several.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 11, 4, 'What do you need to count the “visible” characters with emoji and combining marks?', '["the chars().count() method", "the len() method", "nothing, std can do everything", "grapheme clusters — the unicode-segmentation crate"]', 3, 'chars() counts code points, not graphemes; std has no graphemes.');
